import request from '@/request'

export function getUserList() {
  return request({
    url: '/users',
    method: 'get'
  })
}

export function getUser(id) {
  return request({
    url: `/users/${id}`,
    method: 'get'
  })
}

export function updateUser(user) {
  return request({
    url: '/users/update',
    method: 'post',
    data: user
  })
}

export function deleteUser(id) {
  return request({
    url: `/users/delete/${id}`,
    method: 'get'
  })
}



