<template>
  <div class="dashboard">
    <h2>卫星地面融合网络社区-系统概览</h2>

    <!-- 统计卡片 -->
    <el-row :gutter="20" class="stat-cards">
      <el-col :xs="24" :sm="12" :md="6">
        <el-card class="stat-card">
          <div class="stat-icon" style="background-color: #409EFF;">
            <i class="el-icon-document"></i>
          </div>
          <div class="stat-info">
            <p class="stat-title">文章总数</p>
            <p class="stat-value">{{ stats.articleCount }}</p>
          </div>
        </el-card>
      </el-col>
      <el-col :xs="24" :sm="12" :md="6">
        <el-card class="stat-card">
          <div class="stat-icon" style="background-color: #67C23A;">
            <i class="el-icon-user"></i>
          </div>
          <div class="stat-info">
            <p class="stat-title">用户总数</p>
            <p class="stat-value">{{ stats.userCount }}</p>
          </div>
        </el-card>
      </el-col>
      <el-col :xs="24" :sm="12" :md="6">
        <el-card class="stat-card">
          <div class="stat-icon" style="background-color: #E6A23C;">
            <i class="el-icon-message"></i>
          </div>
          <div class="stat-info">
            <p class="stat-title">评论总数</p>
            <p class="stat-value">{{ stats.commentCount }}</p>
          </div>
        </el-card>
      </el-col>
      <el-col :xs="24" :sm="12" :md="6">
        <el-card class="stat-card">
          <div class="stat-icon" style="background-color: #F56C6C;">
            <i class="el-icon-tag"></i>
          </div>
          <div class="stat-info">
            <p class="stat-title">标签总数</p>
            <p class="stat-value">{{ stats.tagCount }}</p>
          </div>
        </el-card>
      </el-col>
    </el-row>

    <!-- 快速操作 -->
    <el-row :gutter="20" class="quick-actions">
      <el-col :span="24">
        <el-card>
          <div slot="header">
            <span>快速操作</span>
          </div>
          <div class="action-buttons">
            <el-button type="primary" @click="$router.push('/write')">发布文章</el-button>
            <el-button type="success" @click="$router.push('/admin/users')">用户管理</el-button>
            <el-button type="warning" @click="$router.push('/admin/categories')">分类管理</el-button>
            <el-button type="danger" @click="$router.push('/admin/comments')">评论审核</el-button>
          </div>
        </el-card>
      </el-col>
    </el-row>

    <!-- 最新动态 -->
    <el-row :gutter="20" class="recent-activities">
      <el-col :xs="24" :md="12">
        <el-card>
          <div slot="header">
            <span>最新文章</span>
          </div>
          <el-table :data="recentArticles" style="width: 100%">
            <el-table-column prop="title" label="标题" show-overflow-tooltip></el-table-column>
            <el-table-column prop="author" label="作者" width="100">
              <template slot-scope="scope">
                {{ scope.row.author ? scope.row.author.nickname : '-' }}
              </template>
            </el-table-column>
            <el-table-column prop="createDate" label="发布时间" width="120">
              <template slot-scope="scope">
                {{ formatDate(scope.row.createDate) }}
              </template>
            </el-table-column>
          </el-table>
        </el-card>
      </el-col>
      <el-col :xs="24" :md="12">
        <el-card>
          <div slot="header">
            <span>热门文章</span>
          </div>
          <el-table :data="hotArticles" style="width: 100%">
            <el-table-column prop="title" label="标题" show-overflow-tooltip></el-table-column>
            <el-table-column prop="viewCounts" label="浏览量" width="80"></el-table-column>
            <el-table-column prop="commentCounts" label="评论数" width="80"></el-table-column>
          </el-table>
        </el-card>
      </el-col>
    </el-row>
  </div>
</template>

<script>
import { getHotArtices, getNewArtices, listArchives } from '@/api/article'
import { getHotTags, getAllTagsDetail } from '@/api/tag'
import { getUserList } from '@/api/user'
import { getAllCategorysDetail } from '@/api/category'

export default {
  name: 'Dashboard',
  data() {
    return {
      stats: {
        articleCount: 0,
        userCount: 0,
        commentCount: 0,
        tagCount: 0
      },
      recentArticles: [],
      hotArticles: []
    }
  },
  created() {
    this.loadStats()
    this.loadRecentArticles()
    this.loadHotArticles()
  },
  methods: {
    async loadStats() {
      try {
        // 获取标签数量
        const tagRes = await getAllTagsDetail()
        this.stats.tagCount = tagRes && tagRes.data ? tagRes.data.length : 0

        // 获取用户数量
        const userRes = await getUserList()
        this.stats.userCount = userRes && userRes.data ? userRes.data.length : 0

        // 通过归档接口估算文章数量
        const archiveRes = await listArchives()
        if (archiveRes && archiveRes.data && archiveRes.data.length > 0) {
          this.stats.articleCount = archiveRes.data.reduce((sum, item) => sum + (item.articles || 0), 0)
        }
      } catch (error) {
        console.error('加载统计数据失败:', error)
      }
    },
    async loadRecentArticles() {
      try {
        const res = await getNewArtices()
        this.recentArticles = res && res.data ? res.data.slice(0, 5) : []
      } catch (error) {
        console.error('加载最新文章失败:', error)
      }
    },
    async loadHotArticles() {
      try {
        const res = await getHotArtices()
        this.hotArticles = res && res.data ? res.data.slice(0, 5) : []
      } catch (error) {
        console.error('加载热门文章失败:', error)
      }
    },
    formatDate(date) {
      if (!date) return '-'
      return date.substring(0, 10)
    }
  }
}
</script>

<style scoped>
.dashboard {
  padding: 20px;
}

.dashboard h2 {
  margin-bottom: 20px;
  font-size: 24px;
  color: #303133;
}

.stat-cards {
  margin-bottom: 20px;
}

.stat-card {
  display: flex;
  align-items: center;
  padding: 20px;
}

.stat-icon {
  width: 60px;
  height: 60px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 28px;
  color: #fff;
  margin-right: 20px;
}

.stat-info {
  flex: 1;
}

.stat-title {
  margin: 0 0 10px 0;
  color: #909399;
  font-size: 14px;
}

.stat-value {
  margin: 0;
  font-size: 28px;
  font-weight: bold;
  color: #303133;
}

.quick-actions {
  margin-bottom: 20px;
}

.action-buttons {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.recent-activities {
  margin-bottom: 20px;
}

/* 手机端适配 */
@media screen and (max-width: 767px) {
  .dashboard h2 {
    font-size: 18px;
    margin-bottom: 15px;
  }

  .stat-cards {
    margin-bottom: 15px;
  }

  .stat-card {
    flex-direction: column;
    text-align: center;
    padding: 15px;
  }

  .stat-icon {
    width: 50px;
    height: 50px;
    font-size: 24px;
    margin-right: 0;
    margin-bottom: 12px;
  }

  .stat-title {
    font-size: 12px;
    margin-bottom: 8px;
  }

  .stat-value {
    font-size: 22px;
  }

  .action-buttons {
    justify-content: center;
  }
}

/* 平板端适配 */
@media screen and (min-width: 768px) and (max-width: 1024px) {
  .dashboard h2 {
    font-size: 20px;
  }

  .stat-card {
    padding: 18px;
  }

  .stat-icon {
    width: 55px;
    height: 55px;
    font-size: 26px;
    margin-right: 15px;
  }

  .stat-value {
    font-size: 24px;
  }
}
</style>



